.darma-loader-tw-breadcrumb-dots { display: inline-flex; align-items: center; justify-content: center; gap: calc(var(--loader-size, 130px) * .06); width: var(--loader-size, 130px); }
.darma-loader-tw-breadcrumb-dots span { width: calc(var(--loader-size, 130px) * .16); height: calc(var(--loader-size, 130px) * .16); border-radius: calc(var(--loader-size, 130px) * .05); background: var(--loader-color, #8b5cf6); animation: darma-loader-tw-breadcrumb-dots-twCrumb calc(var(--loader-speed, 1s) * 1.6) ease-in-out infinite; }
.darma-loader-tw-breadcrumb-dots i { width: calc(var(--loader-size, 130px) * .07); height: calc(var(--loader-size, 130px) * .07); border-top: calc(var(--loader-size, 130px) * .022) solid color-mix(in srgb, var(--loader-color, #8b5cf6) 55%, transparent); border-right: calc(var(--loader-size, 130px) * .022) solid color-mix(in srgb, var(--loader-color, #8b5cf6) 55%, transparent); transform: rotate(45deg); }
.darma-loader-tw-breadcrumb-dots span:nth-child(3) { animation-delay: calc(var(--loader-speed, 1s) * .25); }
.darma-loader-tw-breadcrumb-dots span:nth-child(5) { animation-delay: calc(var(--loader-speed, 1s) * .5); }
@keyframes darma-loader-tw-breadcrumb-dots-twCrumb { 0%, 100% { opacity: .3; transform: rotate(0deg) scale(.78); } 50% { opacity: 1; transform: rotate(45deg) scale(1); } }

